"regra-de-tres-simples-direta":{"extra":[],"headers":["Quantidade inicial","Valor inicial","Nova quantidade e valor"],"rows":[["3","R$ 18","5 → R$ 30"],["4 m","R$ 56","7 m → R$ 98"],["2 kg","R$ 10","6 kg → R$ 30"]],"faqs":[["Posso usar decimais?","Sim, desde que as unidades sejam consistentes."],["Por que multiplicar cruzado?","É uma consequência da igualdade entre razões."],["Como conferir?","Compare as taxas unitárias dos pares."]],"cta":"Continue aprendendo com as ferramentas, aulas e exercícios comentados do Eduverso."},
